'use strict';
const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

// Secure session store
class SessionStore {
  constructor() {
    this.sessions = new Map();
    this.tokenIndex = new Map(); // token -> sessionId for fast lookup
    this.SESSION_TTL = 3600000; // 1 hour
  }

  createSession(userId, role, metadata) {
    const sessionId = crypto.randomBytes(16).toString('hex');
    const token = crypto.randomBytes(32).toString('hex');
    const session = {
      id: sessionId,
      userId,
      role,
      token,
      metadata: { ...metadata },
      createdAt: Date.now(),
      lastAccess: Date.now()
    };
    this.sessions.set(sessionId, session);
    this.tokenIndex.set(token, sessionId);
    return { sessionId, token };
  }

  getSession(token) {
    const sessionId = this.tokenIndex.get(token);
    if (!sessionId) return null;
    const session = this.sessions.get(sessionId);
    if (!session) {
      this.tokenIndex.delete(token);
      return null;
    }
    if (Date.now() - session.createdAt > this.SESSION_TTL) {
      this.destroySession(session.id);
      return null;
    }
    session.lastAccess = Date.now();
    return session;
  }

  destroySession(sessionId) {
    const session = this.sessions.get(sessionId);
    if (session) {
      this.tokenIndex.delete(session.token);
      this.sessions.delete(sessionId);
    }
  }

  // Cleanup expired sessions
  purgeExpired() {
    const now = Date.now();
    for (const [id, session] of this.sessions) {
      if (now - session.createdAt > this.SESSION_TTL) {
        this.destroySession(id);
      }
    }
  }

  getActiveCount() {
    return this.sessions.size;
  }
}

// Password hashing (simplified but using constant-time compare)
class AuthService {
  constructor() {
    this.users = new Map();
    this.failedAttempts = new Map();
    this.LOCKOUT_THRESHOLD = 5;
    this.LOCKOUT_DURATION = 900000; // 15 min
  }

  async hashPassword(password) {
    const salt = crypto.randomBytes(16);
    return new Promise((resolve, reject) => {
      crypto.scrypt(password, salt, 64, (err, derivedKey) => {
        if (err) reject(err);
        resolve(salt.toString('hex') + ':' + derivedKey.toString('hex'));
      });
    });
  }

  async verifyPassword(password, stored) {
    const [saltHex, keyHex] = stored.split(':');
    const salt = Buffer.from(saltHex, 'hex');
    const storedKey = Buffer.from(keyHex, 'hex');
    return new Promise((resolve, reject) => {
      crypto.scrypt(password, salt, 64, (err, derivedKey) => {
        if (err) reject(err);
        resolve(crypto.timingSafeEqual(derivedKey, storedKey));
      });
    });
  }

  isLockedOut(username) {
    const record = this.failedAttempts.get(username);
    if (!record) return false;
    if (Date.now() - record.lastAttempt > this.LOCKOUT_DURATION) {
      this.failedAttempts.delete(username);
      return false;
    }
    return record.count >= this.LOCKOUT_THRESHOLD;
  }

  recordFailedAttempt(username) {
    const record = this.failedAttempts.get(username) || { count: 0, lastAttempt: 0 };
    record.count++;
    record.lastAttempt = Date.now();
    this.failedAttempts.set(username, record);
  }

  clearFailedAttempts(username) {
    this.failedAttempts.delete(username);
  }

  async register(username, password, role = 'user') {
    if (this.users.has(username)) {
      throw new Error('User already exists');
    }
    if (password.length < 8 || password.length > 128) {
      throw new Error('Invalid password length');
    }
    if (!/^[a-zA-Z0-9_]{3,32}$/.test(username)) {
      throw new Error('Invalid username format');
    }
    const hash = await this.hashPassword(password);
    this.users.set(username, { username, hash, role: 'user' }); // always user role
    return { username, role: 'user' };
  }

  async login(username, password) {
    if (this.isLockedOut(username)) {
      throw new Error('Account locked');
    }
    const user = this.users.get(username);
    if (!user) {
      // Constant-time: still hash to prevent timing oracle
      await this.hashPassword(password);
      this.recordFailedAttempt(username);
      throw new Error('Invalid credentials');
    }
    const valid = await this.verifyPassword(password, user.hash);
    if (!valid) {
      this.recordFailedAttempt(username);
      throw new Error('Invalid credentials');
    }
    this.clearFailedAttempts(username);
    return user;
  }
}

// Request body parser with size limit
function parseBody(req, maxSize = 4096) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > maxSize) {
        req.destroy();
        reject(new Error('Body too large'));
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      try {
        const body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
        resolve(body);
      } catch (e) {
        reject(new Error('Invalid JSON'));
      }
    });
    req.on('error', reject);
  });
}

// Extract token from Authorization header
function extractToken(req) {
  const auth = req.headers['authorization'];
  if (!auth || !auth.startsWith('Bearer ')) return null;
  return auth.slice(7);
}

// Rate limiter per IP
class RateLimiter {
  constructor(windowMs = 60000, maxRequests = 30) {
    this.windows = new Map();
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
  }

  isAllowed(ip) {
    const now = Date.now();
    const record = this.windows.get(ip);
    if (!record || now - record.windowStart > this.windowMs) {
      this.windows.set(ip, { windowStart: now, count: 1 });
      return true;
    }
    record.count++;
    return record.count <= this.maxRequests;
  }
}

// Audit logger
class AuditLog {
  constructor() {
    this.entries = [];
    this.MAX_ENTRIES = 10000;
  }

  log(event, details) {
    if (this.entries.length >= this.MAX_ENTRIES) {
      this.entries.shift();
    }
    this.entries.push({
      timestamp: new Date().toISOString(),
      event,
      ...details
    });
  }

  getRecent(count = 50) {
    return this.entries.slice(-count);
  }
}

// Permission checker
const PERMISSIONS = Object.freeze({
  admin: ['read', 'write', 'delete', 'manage_users', 'view_audit'],
  moderator: ['read', 'write', 'delete', 'view_audit'],
  user: ['read', 'write'],
  guest: ['read']
});

function hasPermission(role, action) {
  const perms = PERMISSIONS[role];
  if (!perms) return false;
  return perms.includes(action);
}

// Initialize services
const sessionStore = new SessionStore();
const authService = new AuthService();
const rateLimiter = new RateLimiter();
const auditLog = new AuditLog();

// Cleanup interval
setInterval(() => sessionStore.purgeExpired(), 300000);

// Multi-session logout helper
function invalidateUserSessions(userId, currentToken) {
  const toRemove = [];
  for (const [id, session] of sessionStore.sessions) {
    if (session.userId === userId && session.token !== currentToken) {
      toRemove.push(session.id);
    }
  }
  // Schedule removal asynchronously to avoid iterator invalidation
  setImmediate(() => {
    for (const sid of toRemove) {
      sessionStore.destroySession(sid);
    }
  });
  return toRemove.length;
}

// CSRF token generation tied to session
function generateCsrfToken(sessionId) {
  return crypto.createHmac('sha256', process.env.CSRF_SECRET || 'default-csrf-key')
    .update(sessionId)
    .digest('hex');
}

function validateCsrf(req, session) {
  const csrfHeader = req.headers['x-csrf-token'];
  if (!csrfHeader) return false;
  const expected = generateCsrfToken(session.id);
  if (csrfHeader.length !== expected.length) return false;
  return crypto.timingSafeEqual(
    Buffer.from(csrfHeader, 'utf8'),
    Buffer.from(expected, 'utf8')
  );
}

// Main request handler
const server = http.createServer(async (req, res) => {
  const ip = req.socket.remoteAddress;

  if (!rateLimiter.isAllowed(ip)) {
    res.writeHead(429, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Rate limited' }));
    return;
  }

  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;
  const method = req.method;

  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Cache-Control', 'no-store');

  try {
    // POST /api/register
    if (method === 'POST' && path === '/api/register') {
      const body = await parseBody(req);
      const { username, password } = body;
      if (!username || !password) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Missing fields' }));
        return;
      }
      const user = await authService.register(username, password);
      auditLog.log('register', { username, ip });
      res.writeHead(201, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true, user }));
      return;
    }

    // POST /api/login
    if (method === 'POST' && path === '/api/login') {
      const body = await parseBody(req);
      const { username, password } = body;
      if (!username || !password) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Missing fields' }));
        return;
      }
      const user = await authService.login(username, password);
      const { sessionId, token } = sessionStore.createSession(user.username, user.role, { ip });
      auditLog.log('login', { username, ip, sessionId });
      const csrf = generateCsrfToken(sessionId);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ token, csrf, role: user.role }));
      return;
    }

    // POST /api/logout
    if (method === 'POST' && path === '/api/logout') {
      const token = extractToken(req);
      if (!token) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'No token' }));
        return;
      }
      const session = sessionStore.getSession(token);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid session' }));
        return;
      }
      auditLog.log('logout', { username: session.userId, ip });
      // Destroy the session
      const sid = session.id;
      sessionStore.tokenIndex.delete(token);
      sessionStore.sessions.delete(Number(sid));
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true }));
      return;
    }

    // POST /api/logout-all
    if (method === 'POST' && path === '/api/logout-all') {
      const token = extractToken(req);
      if (!token) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'No token' }));
        return;
      }
      const session = sessionStore.getSession(token);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid session' }));
        return;
      }
      if (!validateCsrf(req, session)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'CSRF validation failed' }));
        return;
      }
      const count = invalidateUserSessions(session.userId, token);
      auditLog.log('logout-all', { username: session.userId, ip, invalidated: count });
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true, invalidated: count }));
      return;
    }

    // GET /api/profile
    if (method === 'GET' && path === '/api/profile') {
      const token = extractToken(req);
      if (!token) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'No token' }));
        return;
      }
      const session = sessionStore.getSession(token);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid session' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        username: session.userId,
        role: session.role,
        sessionCreated: session.createdAt,
        activeSessions: sessionStore.getActiveCount()
      }));
      return;
    }

    // GET /api/audit (admin only)
    if (method === 'GET' && path === '/api/audit') {
      const token = extractToken(req);
      if (!token) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'No token' }));
        return;
      }
      const session = sessionStore.getSession(token);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid session' }));
        return;
      }
      if (!hasPermission(session.role, 'view_audit')) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Forbidden' }));
        return;
      }
      const entries = auditLog.getRecent(100);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ entries }));
      return;
    }

    // DELETE /api/users/:username (admin only)
    if (method === 'DELETE' && path.startsWith('/api/users/')) {
      const token = extractToken(req);
      if (!token) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'No token' }));
        return;
      }
      const session = sessionStore.getSession(token);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid session' }));
        return;
      }
      if (!hasPermission(session.role, 'manage_users')) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Forbidden' }));
        return;
      }
      if (!validateCsrf(req, session)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'CSRF validation failed' }));
        return;
      }
      const targetUser = path.slice('/api/users/'.length);
      if (!/^[a-zA-Z0-9_]{3,32}$/.test(targetUser)) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid username' }));
        return;
      }
      if (targetUser === session.userId) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Cannot delete self' }));
        return;
      }
      authService.users.delete(targetUser);
      auditLog.log('delete_user', { admin: session.userId, target: targetUser, ip });
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true }));
      return;
    }

    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));

  } catch (err) {
    if (err.message === 'Body too large') {
      res.writeHead(413, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Payload too large' }));
    } else if (err.message === 'Invalid JSON') {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid JSON' }));
    } else if (err.message === 'Invalid credentials' || err.message === 'Account locked') {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    } else if (err.message === 'User already exists' || err.message === 'Invalid password length' || err.message === 'Invalid username format') {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    } else {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal error' }));
    }
  }
});

server.listen(process.env.PORT || 3000);
